import{_ as o,l as i,o as e,c as l,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"k-匿名","description":"","frontmatter":{"title":"k-匿名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/k-anonymity.md","filePath":"cs/k-anonymity.md","lastUpdated":1789023840000}'),c={name:"cs/k-anonymity.md"};function E(k,a,m,_,u,B){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="k-匿名" tabindex="-1">k-匿名 <a class="header-anchor" href="#k-匿名" aria-label="Permalink to &quot;k-匿名&quot;">​</a></h1><div class="epigraph"><p>k-匿名要求每条准标识组合至少对应 k 人。它挡直接指名，挡不住同质敏感值与背景知识。后续有 l-多样与 t-接近，但句法方法仍弱于 DP 的最坏保证。</p><footer>—— Sweeney, k-anonymity, International Journal on Uncertainty, Fuzziness and Knowledge-based Systems, 2002</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/differential-privacy">差分隐私</a>给最坏可加预算。缺口是工程上仍常见的 <strong>k-匿名表</strong>。本课讲它挡什么、不挡什么。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>去掉姓名仍可用邮编+生日+性别再识别。k-匿名泛化准标识。缺口是同质性攻击：k 人同一病。</p><h3 id="组合发布" tabindex="-1">组合发布 <a class="header-anchor" href="#组合发布" aria-label="Permalink to &quot;组合发布&quot;">​</a></h3><p>多张 k-匿名表可交叉破。DP 的组合定理在此缺席。</p><p><span class="marginnote">Sweeney 2002。GDPR 下一课把法律要求接到技术。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 DP。指出医疗公开数据事故作为动机（点名类别，不复盘操作）。下一课 GDPR 技术含义。</p>',12)),(e(),s(p,null,{default:r(()=>[h(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20QID%5B%22%E5%87%86%E6%A0%87%E8%AF%86%22%5D%20--%3E%20GEN%5B%22%E6%B3%9B%E5%8C%96%E5%88%B0%20k%20%E4%BA%BA%E4%B8%80%E7%BB%84%22%5D%0A%20%20GEN%20--%3E%20HOMO%5B%22%E5%90%8C%E8%B4%A8%E6%95%8F%E6%84%9F%E5%80%BC%E4%BB%8D%E6%BC%8F%22%5D%0A%20%20DP%5B%22%E5%B7%AE%E5%88%86%E9%9A%90%E7%A7%81%22%5D%20--%3E%20WORST%5B%22%E6%9C%80%E5%9D%8F%E7%9B%B8%E9%82%BB%E4%BF%9D%E8%AF%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>句法匿名是启发式。法律下一课不会只接受 k。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写再识别教程。GDPR 技术含义下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DP 有预算；k-匿名是句法。</li><li>挡指名，不挡同质与背景知识。</li><li>多表发布会交叉。</li><li>下一课 GDPR。</li><li>出处：Sweeney, 2002；对照 Dwork and Roth。</li></ul>',8))])}const P=o(c,[["render",E]]);export{D as __pageData,P as default};
